per_hop.query:
SELECT ?directorName ?rating WHERE {
  ?film wdt:P31 wd:Q11424;       # Film
        rdfs:label "Boxing Helena"@en;
        wdt:P57 ?director.
  ?director rdfs:label ?directorName FILTER (LANG(?directorName) = "en").
  ?film wdt:P1258 ?rating.       # age rating property
  FILTER (?rating = "15"@en || ?rating = "15")
  FILTER EXISTS {
    wd:Q10783 wdt:P106 wd:Q2526255.   # Martin Scorsese is a director
  }
}
